  AND (SELECT jsonb_agg(jsonb_build_array(actual_column.attname,format_type(actual_column.atttypid,actual_column.atttypmod),actual_column.attnotnull,pg_get_expr(actual_default.adbin,actual_default.adrelid),actual_column.attgenerated,actual_column.attidentity) ORDER BY actual_column.attnum) FROM pg_attribute actual_column LEFT JOIN pg_attrdef actual_default ON actual_default.adrelid=actual_column.attrelid AND actual_default.adnum=actual_column.attnum WHERE actual_column.attrelid='invoice_credit_funding_atomic_fee_partitions'::regclass AND actual_column.attnum>0 AND NOT actual_column.attisdropped)='[["funding_id","uuid",true,null,"",""],["source_payment_id","uuid",true,null,"",""],["source_application_id","uuid",false,null,"",""],["source_invoice_id","uuid",true,null,"",""],["credit_note_id","uuid",true,null,"",""],["credit_note_line_id","uuid",true,null,"",""],["original_charge_receipt_id","uuid",true,null,"",""],["bank_inspection_id","uuid",true,null,"",""],["bank_observation_id","uuid",true,null,"",""],["protocol","text",true,null,"",""],["parent_fingerprint","text",true,null,"",""],["economics","jsonb",true,null,"",""],["before_entries","jsonb",true,null,"",""],["admission_transaction_id","text",true,null,"",""],["digest","text",true,null,"",""],["authentication","text",true,null,"",""],["created_at","timestamp with time zone",true,"now()","",""]]'::jsonb
